type TSkill = { icon: () => JSX.Element; description: string | JSX.Element };

function IconBox({ iconName, className, children }: BasicProps & { iconName: string }) {
  return (
    <Badge
      variant={'outline'}
      className={cn('text-xs [&>svg]:size-4 p-0 rounded-none border-none font-extrabold', className)}
    >
      <svg aria-hidden="true" focusable="false" viewBox="0 0 128 128" data-icon={iconName} data-inline="false">
        {children}
      </svg>
      {iconName}
    </Badge>
  );
}

